    # Build the graph with railways
    for u, v in railways:
        graph[u].append(v)
        graph[v].append(u)

    # Check if it's possible for the bus to reach town n
    visited = [False] * (n + 1)
    queue = deque([1])
    visited[1] = True

    while queue:
        current = queue.popleft()
        for neighbor in range(1, n + 1):
            if not visited[neighbor] and neighbor not in graph[current]:
                visited[neighbor] = True
                queue.append(neighbor)

    if not visited[n]:
        return -1

    # BFS to find the minimum time for the train to reach town n
    train_queue = deque([(1, 0)])
    train_visited = {1}

    while train_queue:
        current, time = train_queue.popleft()
        if current == n:
            return max(time, bfs_to_reach_n_with_bus(graph, visited, n))

        for neighbor in graph[current]:
            if neighbor not in train_visited:
                train_visited.add(neighbor)
                train_queue.append((neighbor, time + 1))

    return -1

def bfs_to_reach_n_with_bus(graph, visited, n):
    bus_queue = deque([(i, 0) for i in range(1, n + 1) if visited[i]])
    bus_visited = set(bus_queue)

    while bus_queue:
        current, time = bus_queue.popleft()
        if current == n:
            return time

        for neighbor in range(1, n + 1):
            if neighbor not in bus_visited and neighbor not in graph[current]:
                bus_visited.add(neighbor)
                bus_queue.append((neighbor, time + 1))

    return float('inf')

